head.b:skin:
/*!
=> Theme Name: Anime.xml Pro
=> Theme URI: https://shop.zkreations.com
=> Author: Daniel Abel M. (Copyright 2019 zkreations)
=> Author URI: https://fb.com/danieI.abel
=> Version: 4.3.0
=> License: Creative Commons Atribucion-NoComercial 4.0 Internacional
=> License URI: http://creativecommons.org/licenses/by-nc/4.0/
*/

/*Fix: Unnecessary elements removed*/ 
.widget-item-control,.item-control.blog-admin,
.continue,.loadmore,.thread-chrome.thread-collapsed,
.singleton-element:not(.cookie-choices-info),
.noAllowNewComments .comment-reply,
.comments .hidden {display:none}

/*Fix: Show lightbox*/
.CSS_LIGHTBOX{z-index:90001!important}

/*Fix: Responsive images*/
a[style^=margin-left],
a[imageanchor]:not([style*=float]) {
    margin-right: 0 !important;
    margin-left: 0 !important;
}

.widget-content img,
img[data-original-height],
img[data-original-width] {height: auto;}

/*Fix: Responsive videos*/
.BLOG_video_class, .b-hbp-video, .b-uploade {
    max-width: 100%;
}

/*Fix: Comment Editor*/
#comment-editor{
    border:0;
    width:100%;
    min-height:220px
}

/* Configurations
   ====================
   <!-- General Options -->
   <Variable name="config.comments" description="Comment system" type="string" default="blogger" value="blogger"/>
   <Variable name="config.shortname" description="Shortname of Disqus" type="string" default="shortname" value="shortname"/>
   <Variable name="config.dark" description="Main is dark?" type="string" default="true" value="true"/>
   <Variable name="config.dark.footer" description="Footer is dark?" type="string" default="true" value="true"/>

   <!-- Animate.css -->
   <Variable name="config.animate.search" description="Search engine animation" type="string" default="fadeInDown .5s" value="fadeInDown .5s"/>
   <Variable name="config.animate.menu" description="Menu animation" type="string" default="flipInX .5s" value="flipInX .5s"/>
   <Variable name="config.animate.menu.mobile" description="Mobile menu animation" type="string" default="fadeInLeft .5s" value="fadeInLeft .5s"/>
   <Variable name="config.animate.cover" description="Article Animation" type="string" default="fadeIn .5s" value="fadeIn .5s"/>
   <Variable name="config.animate.cover.text" description="Article Animation (Icon)" type="string" default="fadeInDown .5s" value="fadeInDown .5s"/>
   <Variable name="config.animate.lazy" description="LazyLoad Animation" type="string" default="fadeIn .5s" value="fadeIn .5s"/>

   <!-- Admin Options -->
   <Variable name="config.admin.dark" description="Admin is dark?" type="string" default="false" value="false"/>
   <Variable name="config.admin.showInfo" description="Show widget subtitles" type="string" default="false" value="false"/>

   <!-- Bundle.css -->
   <Variable name="config.bundle.ctheme" description="Bundle comment theme" type="string" default="anime" value="anime"/>

   <!-- Cards (Home posts) -->
   <Variable name="config.post.style" description="Home post style" type="string" default="grid" value="grid"/>
   <Variable name="config.post.column" description="Number of columns" type="string" default="2" value="3"/>
   <Variable name="config.post.showSnippet" description="Show Snippet" type="string" default="true" value="true"/>
   <Variable name="config.post.showMeta" description="Show Meta" type="string" default="true" value="true"/>
   <Variable name="config.post.showShare" description="Show Share Buttons" type="string" default="true" value="true"/>

   <!-- Image Ratio -->
   <Variable name="config.ratio.post" description="Aspect ratio" type="string" default="true" value="true"/>
   <Variable name="config.ratio.slider" description="Aspect ratio (Slider)" type="string" default="true" value="true"/>
   <Variable name="config.ratio.featured" description="Aspect ratio (Featured Post)" type="string" default="true" value="true"/>
   <Variable name="config.ratio.populars" description="Aspect ratio (Popular posts)" type="string" default="true" value="true"/>

   <!-- Show -->
   <Variable name="config.show.homeSidebar" description="Show Home sidebar" type="string" default="true" value="false"/>
   <Variable name="config.show.postSidebar" description="Show Post sidebar" type="string" default="true" value="true"/>
   <Variable name="config.show.pageSidebar" description="Show Page sidebar" type="string" default="true" value="true"/>
   <Variable name="config.show.errorSidebar" description="Sidebar on Error" type="string" default="true" value="true"/>
   <Variable name="config.show.footerWidgets" description="Show footer widgets section" type="string" default="true" value="true"/>
   <Variable name="config.show.postPager" description="Show pagination in entrys" type="string" default="true" value="true"/>
   <Variable name="config.show.search" description="Show menu search" type="string" default="true" value="true"/>

   <!-- Funtions -->
   <Variable name="config.el.stickySidebar" description="Sticky Sidebar" type="string" default="false" value="false"/>
   <Variable name="config.el.oppositeBlog" description="Exchange between sidebar and blog" type="string" default="false" value="false"/>
   <Variable name="config.el.boxed" description="Wide container" type="string" default="true" value="true"/>
   <Variable name="config.el.postsRelated" description="Related entries" type="string" default="true" value="true"/>
   <Variable name="config.el.postsRelated.num" description="Number of posts related" type="string" default="2" value="2"/>
   <Variable name="config.el.postsRelated.column" description="Columns of posts related" type="string" default="2" value="2"/>
   <Variable name="config.el.localeDate" description="Time formatting" type="string" default="en-Us" value="en-Us"/>
   <Variable name="config.el.featureTags" description="Feature Tags" type="string" default="false" value="false"/>
   <Variable name="config.el.featureTags.tags" description="Array of labels" type="string" default="" value=""/>

   <!-- Search results -->
   <Variable name="config.search.altSearch" description="Alternative search page style" type="string" default="true" value="true"/>
   <Variable name="config.search.maxResults" description="Max search results" type="string" default="true" value="true"/>
   <Variable name="config.search.maxResults.num" description="Number of search results" type="string" default="10" value="10"/>

   <!-- image default -->
   <Variable name="config.default.image" description="Default image" type="string" default="https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEivr85dqYHoDb4tDoNlQU4OpvDd_PKCrEcofdURlmfFQ4iE5Gdv-OLD-pRehw7ZMnQMCqI-IITqLIzTV3w8aejbWRSO6kCz9x7TTq1fqX1OnmV1oACxokYO1MSaFZo0hqG7MecPpU2-kHI/s1600/no-img-blogger.png" value="https://2.bp.blogspot.com/-1J-byOnRoAI/W3Cot79qVUI/AAAAAAAADmE/IwXCcRdJl70_yR7FivfpmM62MVqD4CwbQCLcBGAs/s1600/no-img-blogger.png"/>

   <!-- Default messages -->
   <Variable name="config.msj.nojs" description="Javascript Disable" type="string" default="Javascript required" value="Javascript required"/>

   Variable definitions
   ====================

   <Variable name="keycolor" description="Main Color" type="color" default="#2196f3" value="#649d7c"/>

   <Group description="Accents" selector="body">
      <Variable name="main.bg" description="Main Background" type="color" default="#1b1f21" value="#000000"/>
      <Variable name="main.color" description="Main Background Color" type="color" default="#23a6b3" value="#22af2c"/>
      <Variable name="main.linkColor" description="Link color" type="color" default="#23a6b3" value="#22af2c"/>
   </Group>

   <Group description="Widths" selector=".main">
      <Variable name="width.content" description="Content width" type="length" min="800px" max="1600px" default="1240px" value="1240px"/>
      <Variable name="width.sidebar" description="Sidebar width" type="length" min="100px" max="600px" default="340px" value="340px"/>
      <Variable name="width.margin" description="Content margin" type="length" min="0" max="50px" default="30px" value="30px"/>
      <Variable name="header.margin" description="Header separation" type="length" min="0" max="200px" default="30px" value="30px"/>
      <Variable name="main.margin" description="Content separation" type="length" min="0" max="100px" default="30px" value="30px"/>
      <Variable name="footer.margin" description="Footer separation" type="length" min="0" max="100px" default="30px" value="30px"/>
   </Group>

   <Group description="Content font" selector="body">
      <Variable name="font.logo" description="Title Font" type="font" size="34px" family="Custom" default="$(size) $(family)" value="normal normal 34px Open Sans"/>
      <Variable name="font.text" description="Content font" type="font" family="Custom" default="$(family)" value="normal normal 100% Open Sans"/>
      <Variable name="font.desc" description="Blog Description Font" type="font" size="14px" family="Custom" default="$(size) $(family)" value="normal normal 14px Open Sans"/>
   </Group>

   <Group description="Content color" selector=".main">
      <Variable name="body.bg" description="Page Background Color" type="color" default="#060606" value="#000000"/>
      <Variable name="body.colorTitle" description="Title Color" type="color" default="#ffffff" value="#ffffff"/>
      <Variable name="body.colorText" description="Text Color" type="color" default="#eeeeee" value="#eeeeee"/>
   </Group>

   <Group description="Header" selector=".header__wrapper">
      <Variable name="header.bg" description="Header Background" type="color" default="#191919" value="#000000"/>
      <Variable name="header.colorLogo" description="Blog Title Color" type="color" default="#ffffff" value="#ffffff"/>
      <Variable name="header.colorDesc" description="Blog Description Color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="iTicker" selector=".iTicker">
      <Variable name="iticker.bg" description="Background Color" type="color" default="#191919" value="#000000"/>
      <Variable name="iticker.title" description="Title Color" type="color" default="#ffffff" value="#ffffff"/>
      <Variable name="iticker.color" description="Text Color" type="color" default="#757575" value="#737373"/>
   </Group>

   <Group description="Header Bar" selector=".header__menu">
      <Variable name="menu.bg" description="Background Color" type="color" default="#131313" value="#000000"/>
      <Variable name="menu.color" description="Color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="Gadgets" selector=".sidebar .widget">
      <Variable name="gadget.bg" description="Gadget Background" type="color" default="transparent" value="rgba(0,0,0,0)"/>
      <Variable name="gadget.title" description="Background Color" type="color" default="#131313" value="#000000"/>
      <Variable name="gadget.margin" description="Widget separation" type="length" min="0" max="50px" default="0" value="0"/>
      <Variable name="gadget.color" description="Gadget Title Color" type="color" default="#ffffff" value="#ffffff"/>
      <Variable name="gadget.icon" description="Icon color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="Posts" selector=".card__content">
      <Variable name="post.bg" description="Post background color" type="color" default="#131313" value="#000000"/>
      <Variable name="post.margin" description="Content margin" type="length" min="0" max="80px" default="28px" value="28px"/>
      <Variable name="post.titleColor" description="Post Title Color" type="color" default="#ffffff" value="#ffffff"/>
      <Variable name="post.dateColor" description="Date Header Color" type="color" default="#999999" value="#989898"/>
      <Variable name="post.borderRadius" description="Post border radius" type="length" min="0" max="50px" default="0" value="0"/>
      <Variable name="post.snippetColor" description="Post text color" type="color" default="#eeeeee" value="#eeeeee"/>
      <Variable name="post.share" description="Sharing" type="color" default="rgba(255, 255, 255, 0.2)" value="rgba(255,255,255,0.2)"/>
      <Variable name="post.shareColor" description="Sharing icons color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="Sharing" selector=".footer__primary">
      <Variable name="footer.primaryBg" description="Background Color" type="color" default="#131313" value="#000000"/>
      <Variable name="footer.shareColor" description="Sharing icons color" type="color" default="rgba(255, 255, 255, 0.4)" value="rgba(255,255,255,0.4)"/>
      <Variable name="footer.linksText" description="Text Color" type="color" default="rgba(255, 255, 255, 0.4)" value="rgba(255,255,255,0.4)"/>
      <Variable name="footer.linksColor" description="Footer Color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="Footer" selector=".footer__widgets .widget">
      <Variable name="footer.bg" description="Footer Background" type="color" default="#060606" value="#000000"/>
      <Variable name="footer.gadgetBg" description="Gadget Background" type="color" default="transparent" value="rgba(0,0,0,0)"/>
      <Variable name="footer.gadgetMargin" description="Content margin" type="length" min="0" max="50px" default="0" value="0"/>
      <Variable name="footer.gadgetTitle" description="Background Color" type="color" default="rgba(255,255,255,0.05)" value="rgba(255,255,255,0.047)"/>
      <Variable name="footer.gadgetColor" description="Gadget Title Color" type="color" default="#ffffff" value="#ffffff"/>
      <Variable name="footer.gadgetIcon" description="Icon color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Group description="Footer Links" selector=".footerLinks">
      <Variable name="footer.linksBg" description="Footer Background" type="color" default="#131313" value="#000000"/>
      <Variable name="footer.IconColor" description="Icon color" type="color" default="#414141" value="#3a3a3a"/>
      <Variable name="footer.links" description="Link Color" type="color" default="#ffffff" value="#ffffff"/>
   </Group>

   <Variable name="body.background" description="Main Background" type="background" color="$(main.bg)" default="$(color) none repeat scroll top center" value="$(color) none repeat scroll top center"/>
*/

body {
    background: $(body.background);
    font-family: '$(font.text.family)', 'Roboto', sans-serif;
}
.skin-font,
.widget-title,
.logo__title {
    font-family: '$(font.logo.family)', 'Oswald', sans-serif;
}
.logo__descripcion {
    font-family: '$(font.desc.family)', 'Roboto', sans-serif;
}
.container {
    max-width: $(width.content);
}
@media (min-width: 576px) {
    .logo__title {
        font-size: $(font.logo.size);
    }
    .logo__descripcion {
        font-size: $(font.desc.size);
    }
}
/* Main Colors
-----------------------------------*/
/*color*/
a, a:hover,
.skin-color,
.skin-color-hover:hover,
.tagsList__link.here,
.pageLink.is-selected .btn,
.drop-caps:first-letter {
    color: $(main.linkColor);
}
.gallery__href::before,
.card__overlay::before,
.pageLink.is-selected .btn,
.widget-name,
.nav__menu > li:hover,
.nav__menu a.is-currentUrl,
.dropdown-menu li > ul,
.tagsList__link.here {
    background-color: $(main.color) !important;
}
::-moz-selection {
    background-color: $(main.color);
}
::selection {
    background-color: $(main.color);
}
.ftag-name,
.skin-bg,
.widget-more-item,
.skin-bg-hover:hover,
.contact-form-button,
.wjs-item.is-active {
    background-color: $(main.color);
}
.wjs-tab:not(.tab-vertical) .tab-header {
    border-bottom: 2px solid $(main.color);
}
.tab-vertical .tab-header {
    border-right: 2px solid $(main.color);
}
blockquote,
.footer__primary,
.post-body blockquote {
    border-color: $(main.color);
}
/* Body Colors
-----------------------------------*/
h1, h2, h3, h4, h5, h6,
.h1, .h2, .h3, .h4, .h5, .h6,
.skin-color-title {
    color: $(body.colorTitle);
}
.skin-color-text {
    color: $(body.colorText);
}
/* Header
-----------------------------------*/
.header {
    background-color: $(header.bg);
}
.search-container input {
   -webkit-animation: $(config.animate.search);
           animation: $(config.animate.search);
}
.card__image:hover .card__overlay::before {
   -webkit-animation: $(config.animate.cover);
           animation: $(config.animate.cover);
}
.card__readMore::before,
.portfolio-meta-content .card__title,
.authorPortfolio  {
   -webkit-animation: $(config.animate.cover.text);
           animation: $(config.animate.cover.text);
}
.img-change {
   -webkit-animation: $(config.animate.lazy);
           animation: $(config.animate.lazy);
   -webkit-animation-fill-mode: both;
           animation-fill-mode: both;
   -webkit-animation-play-state: paused;
           animation-play-state: paused;
}
.img-loaded {
   -webkit-animation-play-state: running;
           animation-play-state: running;
}
/*Menu*/
.header__menu {
    background-color: $(menu.bg);
}
@media (max-width: 991px) {
    .nav__menu {
        background-color: $(menu.bg);
        -webkit-animation: $(config.animate.menu.mobile);
                animation: $(config.animate.menu.mobile);
    }
    .nav__menu a.is-active {
        background-color: $(main.color);
    }
}
.nav__toggle--icon span,
.nav__toggle--icon span::after,
.nav__toggle--icon span::before {
   background-color: $(menu.color);
}
.logo__link:hover,
.logo__link {
    color: $(header.colorLogo);
}
.logo__descripcion {
    color: $(header.colorDesc);
}
@media (min-width: 992px) {
    .main {
        padding-top: $(main.margin);
        padding-bottom: $(main.margin);
    }
    .header__wrapper {
        padding-top: $(header.margin);
        padding-bottom: $(header.margin);
    }
}
/* iTicker
-----------------------------------*/
.iTicker {
    background: $(iticker.bg);
}
.iTicker-info i,
.iTicker-name {
    color: $(iticker.title);
}
.iTicker-link {
    color: $(iticker.color);
}
/* Layout
-----------------------------------*/
.main {
    background-color: $(body.bg);
}
.search-btn {
    color: $(menu.color);
}
.nav__menu a {
    color: $(menu.color);
}
@media (min-width: 992px) {
    .nav__menu li:hover > ul {
      -webkit-animation: $(config.animate.menu);
              animation: $(config.animate.menu);
    }
    .blog {
        width: calc(100% - $(width.sidebar) - $(width.margin));
    }
    .sidebar {
        width: $(width.sidebar);
    }
    .main,
    .footer-wrapper,
    .header .header__nav,
    .header .iTicker,
    .header__wrapper {
        padding-left: $(width.margin);
        padding-right: $(width.margin);
    }
    .Image__full {
        margin-left: -$(main.margin);
        margin-right: -$(main.margin);
    }
    .footer__items {
        margin-left: calc(-$(width.margin) / 2);
        margin-right: calc(-$(width.margin) / 2);
    }
    .stickySidebar {
        position: -webkit-sticky;
        position: sticky;
        top: $(width.margin);
    }
    .footer__case {
        padding-left: calc($(width.margin) / 2);
        padding-right: calc($(width.margin) / 2);
    }
}
/* Cards
-----------------------------------*/
.card__content {
    background-color: $(post.bg);
    border-radius: $(post.borderRadius);
    overflow: hidden;
    position: relative;
}
.card__title,
.card__title a {
    color: $(post.titleColor);
}
.card__item {
    color: $(post.dateColor);
}
.post-body,
.card__descripcion {
    color: $(post.snippetColor);
}
.btn-border,
.shareFeatured .btn,
.shareButtons .btn {
    border-color: $(post.share);
    color: $(post.shareColor);
}
@media (min-width: 576px) {
    .wjs-recentCmts,
    .card__data {
        padding: $(post.margin);
    }
    .wjs-cmts__card:not(:last-child) {
        margin-bottom: $(post.margin);
    }
    .postCover-common,
    .article .card__header {
        margin-bottom: $(main.margin);
    }
    .pagerPost,
    .post-related,
    .postComments,
    .shareButtons:not(.card__share) {
        padding-top: $(main.margin);
    }
}
/* Widgets
-----------------------------------*/
.main .widget {
    background-color: $(gadget.bg);
}
.main .widget-title {
    background-color: $(gadget.title);
}
.main .widget-title i {
    color: $(gadget.icon);
}
.widget-more-item,
.widget-more-item:hover,
.main .widget-name {
    color: $(gadget.color);
}
/* Footer
-----------------------------------*/
.footer {
    background-color: $(footer.bg);
}
.footer__primary  {
    background: $(footer.primaryBg);
}
.socialList-item {
    color: $(footer.shareColor);
}
.footer__widgets .widget {
    background-color: $(footer.gadgetBg);
}
.footer .widget-title {
    background-color: $(footer.gadgetTitle);
}
.footer .widget-title i {
    color: $(footer.gadgetIcon);
}
.footer .widget-name {
    color: $(footer.gadgetColor);
}
.footerLink .fas {
    color: $(footer.IconColor);
}
.footerLink {
    color: $(footer.links);
}
@media (min-width: 992px) {
    .footer__widgets {
        padding-top: $(footer.margin);
        padding-bottom: $(footer.margin);
    }
    .footer__widgets .widget {
        padding: $(footer.gadgetMargin);
    }
    .main .widget {
        padding: $(gadget.margin);
    }
    .main__general .widget:last-child,
    .article:not(:last-child),
    .widget:not(:last-child) {
        margin-bottom: $(width.margin);
    }
    .skin-box {
        padding: $(width.margin);
    }
}
/* Footer Copy
-----------------------------------*/
.footerLinks {
    background-color: $(footer.linksBg);
}
.copy__date,
.copy__attribution {
    color: $(footer.linksText);
}
.copy__attribution a {
    color: $(footer.linksColor);
}
/* Espaciado entre párrafos */
.post-body p {
  margin-bottom: 1.2em;
  line-height: 1.6;
}

/* Espaciado entre listas y sus elementos */
.post-body ul,
.post-body ol {
  margin-bottom: 1.2em;
  padding-left: 1.5em;
}

.post-body li {
  margin-bottom: 0.5em;
  line-height: 1.6;
}

/* Espaciado para tablas */
.post-body table {
  margin-bottom: 1.5em;
  border-collapse: collapse;
  width: 100%;
}

.post-body th,
.post-body td {
  padding: 10px;
  border: 1px solid #ddd;
  text-align: left;
  line-height: 1.5;
}

/* Espaciado para bloques de código y citas */
.post-body blockquote,
.post-body pre {
  margin-bottom: 1.2em;
  padding: 10px;
  background-color: #f8f8f8;
  border-left: 4px solid #ccc;
}

/* Espaciado para encabezados */
.post-body h2,
.post-body h3,
.post-body h4,
.post-body h5,
.post-body h6 {
  margin-top: 1.5em;
  margin-bottom: 0.6em;
  line-height: 1.4;
}

/* ----- MENÚ PERSONALIZADO HOUSE GATITOS ----- */
/* 🎨 Submenú pegado al botón padre, sin separación */
.header .nav__menu li {
  position: relative;
}

.header .nav__menu li ul {
  position: absolute;
  top: 100%; /* Justo debajo del botón padre, sin margen */
  left: 0;
  background-color: #20bf55; /* verde original */
  border-radius: 10px;
  padding: 0.4em 0;
  box-shadow: 0 6px 12px rgba(0, 0, 0, 0.2);
  z-index: 999;
}

.header .nav__menu li ul li a {
  display: block;
  padding: 0.6em 1.2em;
  color: #fff;
  font-weight: 500;
  white-space: nowrap;
}

.header .nav__menu li ul li a:hover {
  background-color: #1a9442; /* un verde más oscuro para hover */
}

.galeria-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
  margin-top: 2rem;
}

.tarjeta-gato {
  background-color: #1a1a1a;
  border-radius: 1rem;
  overflow: hidden;
  transition: transform 0.3s;
  box-shadow: 0 4px 8px rgba(0,0,0,0.4);
}

.tarjeta-gato a {
  display: block;
  color: white;
  text-decoration: none;
  padding: 1rem;
}

.tarjeta-gato img {
  width: 100%;
  height: auto;
  border-radius: 0.5rem;
}

.tarjeta-gato h3 {
  margin: 0.8rem 0 0.5rem;
  color: #ff6f61;
  font-size: 1.2rem;
}

.tarjeta-gato p {
  font-size: 0.95rem;
  line-height: 1.4;
}

.tarjeta-gato .ver-mas {
  display: inline-block;
  margin-top: 0.8rem;
  color: #22af2c;
  font-weight: bold;
}

.tarjeta-gato:hover {
  transform: scale(1.03);
}

/* === HG Patch v5.1 (CDATA) === */

/* === HG Patch v5.1 — Integración CSS Home (site-wide) === */
:root { --hg-accent:#22af2c; --hg-accent-2:#ff6f61; --hg-text:#f0f3f2; --hg-muted:#b8c2c0; --hg-border:#2c3332; --hg-card:#111514; }
.hg-home section, .hg-home .seccion-informativa, .hg-home .galeria-razas { font-family:inherit; font-size:1.075rem; line-height:1.9; color:var(--hg-text); text-align:left; margin:1.75rem 0 2rem; text-wrap:pretty; -webkit-hyphens:none; hyphens:none; }
.hg-home section>p,.hg-home section>ul,.hg-home section>ol{max-width:72ch;margin-inline:auto;padding-inline:4px;text-wrap:pretty}
.hg-home section p,.hg-home .galeria-razas p{margin-bottom:1rem}
.hg-home section h2,.hg-home .galeria-razas h2{font-size:1.75rem;color:var(--hg-accent);margin:2rem 0 1rem;text-align:center;letter-spacing:.2px;text-wrap:balance}
.hg-home section h3{font-size:1.25rem;color:var(--hg-accent-2);margin:1.25rem 0 .75rem;letter-spacing:.2px;text-wrap:balance}
.hg-home section ul{margin:0 0 1.2rem 1.5rem;list-style:disc}
.hg-home section ol{margin:0 0 1.2rem 1.5rem}
.hg-home section li{margin-bottom:.5rem}
.hg-home section strong{color:#fff}
.hg-home section a{color:#c8ffd0;text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:.08em}
.hg-home section a:hover{color:#eaffef}
.hg-home figure{margin:18px auto;max-width:72ch;text-align:center}
.hg-home figure img,.hg-home section img{max-width:100%;height:auto;border-radius:12px;display:block;margin-inline:auto}
.hg-home figure figcaption{margin-top:8px;font-size:.95em;color:var(--hg-muted)}
.hg-home .btn{display:inline-block;padding:10px 16px;border-radius:8px;background:#1769e0;color:#fff!important;text-decoration:none;font-weight:600;border:1px solid transparent}
.hg-home .btn:hover{filter:brightness(1.05)}
.hg-home .galeria-grid{display:grid;gap:14px;grid-template-columns:repeat(2,1fr);margin-top:2rem}
@media (min-width:860px){.hg-home .galeria-grid{grid-template-columns:repeat(4,1fr)}}
.hg-home .tarjeta-gato{background:var(--hg-card);border:1px solid var(--hg-border);border-radius:12px;overflow:hidden;transition:transform .15s,box-shadow .15s,border-color .15s;box-shadow:0 4px 8px rgba(0,0,0,.25)}
.hg-home .tarjeta-gato a{display:block;color:inherit;text-decoration:none}
.hg-home .tarjeta-gato img{width:100%;height:auto;display:block;border-radius:0}
.hg-home .tarjeta-gato h3{font-size:1.05rem;margin:.6rem .75rem 0;color:#fff;text-align:left}
.hg-home .tarjeta-gato p{margin:.4rem .75rem .5rem;color:var(--hg-muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-align:left;text-wrap:pretty;-webkit-hyphens:none;hyphens:none}
.hg-home .tarjeta-gato .ver-mas{display:inline-block;margin:.25rem .75rem .8rem;font-weight:600;color:#c8ffd0}
.hg-home .tarjeta-gato:hover{transform:translateY(-2px);border-color:#3a4745;box-shadow:0 8px 18px rgba(0,0,0,.25)}
.hg-home .cta-secundaria,.hg-home [role="region"]{background:linear-gradient(180deg,rgba(17,21,20,.06),rgba(17,21,20,.04));border:1px solid var(--hg-border);border-radius:10px}
.hg-home details{background:rgba(17,21,20,.04);border:1px solid var(--hg-border);border-radius:10px;padding:10px 12px}
.hg-home details+details{margin-top:8px}
.hg-home summary{cursor:pointer;font-weight:600;color:#fff}
.hg-home .faq-details p{color:var(--hg-muted)}
.hg-home table{width:100%;border-collapse:collapse;margin:12px 0 16px;font-size:.98rem}
.hg-home th,.hg-home td{border:1px solid var(--hg-border);padding:10px 12px;text-align:left}
.hg-home th{background:#15201e;color:#e9fff0}
.hg-home tr:nth-child(even){background:rgba(17,21,20,.35)}
.hg-home iframe{border:1px solid var(--hg-border);border-radius:10px}
.hg-home #guias-esenciales>p:last-of-type,.hg-home #herramientas>p:last-of-type,.hg-home #nutricion-salud>p:last-of-type,.hg-home #comportamiento-bienestar>p:last-of-type,.hg-home #adopcion-primeros-cuidados>p:last-of-type,.hg-home #curiosidades>p:last-of-type{margin-bottom:1.25rem}
.hg-home .post-body{font-family:inherit;font-size:1.075rem;line-height:1.9;color:var(--hg-text);text-align:left;text-wrap:pretty;-webkit-hyphens:none;hyphens:none}
.hg-home .post-body>p,.hg-home .post-body>ul,.hg-home .post-body>ol{max-width:72ch;margin-inline:auto;padding-inline:4px}
.hg-home .post-body p{margin-bottom:1rem}
.hg-home .post-body h2{font-size:1.75rem;color:var(--hg-accent);margin:2rem 0 1rem;text-align:center;letter-spacing:.2px;text-wrap:balance}
.hg-home .post-body h3{font-size:1.25rem;color:var(--hg-accent-2);margin:1.25rem 0 .75rem;letter-spacing:.2px;text-wrap:balance}
.hg-home .post-body strong{color:#fff}
.hg-home .post-body a{color:#c8ffd0;text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:.08em}
.hg-home .post-body a:hover{color:#eaffef}
.hg-home .post-body figure{margin:18px auto;max-width:72ch;text-align:center}
.hg-home .post-body figure img,.hg-home .post-body img{max-width:100%;height:auto;border-radius:12px;display:block;margin-inline:auto}
.hg-home .post-body figure figcaption{margin-top:8px;font-size:.95em;color:var(--hg-muted)}
.hg-home .post-body table{width:100%;border-collapse:collapse;margin:12px 0 16px;font-size:.98rem}
.hg-home .post-body th,.hg-home .post-body td{border:1px solid var(--hg-border);padding:10px 12px;text-align:left}
.hg-home .post-body th{background:#15201e;color:#e9fff0}
.hg-home .post-body tr:nth-child(even){background:rgba(17,21,20,.35)}
.hg-home .post-body iframe{border:1px solid var(--hg-border);border-radius:10px}
@media (max-width:860px){.hg-home section,.hg-home .seccion-informativa,.hg-home .galeria-razas,.hg-home .post-body{font-size:1.06rem;line-height:1.95}.hg-home section>p,.hg-home section>ul,.hg-home section>ol,.hg-home figure,.hg-home .post-body>p,.hg-home .post-body>ul,.hg-home .post-body>ol{max-width:100%}.hg-home .galeria-grid .tarjeta-gato p{-webkit-hyphens:auto;hyphens:auto}}
@media (max-width:480px){.hg-home section,.hg-home .seccion-informativa,.hg-home .galeria-razas,.hg-home .post-body{font-size:1rem;line-height:1.85}.hg-home section h2,.hg-home .post-body h2{font-size:1.45rem}.hg-home section h3,.hg-home .post-body h3{font-size:1.15rem}}
.hg-home section>p,.hg-home section>ul,.hg-home section>ol,.hg-home figure{max-width:none!important;margin-inline:0!important;padding-inline:0!important}
.hg-home p[style*="max-width"],.hg-home figure[style*="max-width"]{max-width:none!important}
.hg-home section h2{margin-bottom:1.25rem}
.hg-home [role="region"]{border-color:var(--hg-border)!important}
@media (min-width:1280px){.hg-home section{font-size:1.04rem;line-height:1.9}}



