body.script:
//
// HouseGatitos LCP/Lazy patch v1 (2025-09-30)
// Prioriza la primera imagen del post (LCP) y aplica lazy al resto.
// También intenta asegurar dimensiones para reducir CLS.
(function(){'use strict';
  function enhanceContainer(container){
    if(!container) return;
    var imgs = container.querySelectorAll('img');
    if(!imgs || !imgs.length) return;
    // Héroe (LCP): primera imagen del post
    var hero = imgs[0];
    try {
      hero.setAttribute('decoding','async');
      hero.setAttribute('fetchpriority','high');
      // Asegura carga no diferida en la LCP
      hero.setAttribute('loading','eager');
    } catch(e){}
    // Resto de imágenes: lazy + decoding async
    for (var i=1;i<imgs.length;i++){ 
      try {
        if(!imgs[i].hasAttribute('loading')) imgs[i].setAttribute('loading','lazy');
        if(!imgs[i].hasAttribute('decoding')) imgs[i].setAttribute('decoding','async');
      } catch(e){}
    }
    // Intento de fijar dimensiones para evitar CLS
    (imgs.forEach ? imgs : Array.prototype.slice.call(imgs)).forEach(function(img){
      try {
        var w = parseInt(img.getAttribute('width') || img.getAttribute('data-original-width') || 0, 10);
        var h = parseInt(img.getAttribute('height') || img.getAttribute('data-original-height') || 0, 10);
        if (w>0 && h>0){
          img.setAttribute('width', w);
          img.setAttribute('height', h);
          if(!img.style.aspectRatio) img.style.aspectRatio = w + ' / ' + h;
        }
      } catch(e){}
    });
  }
  function run(){
    var post = document.querySelector('.post-body, article .post-body, article .entry-content, article .post, article');
    enhanceContainer(post);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run);
  } else { run(); }
})();
//

//
(function(){'use strict';
  function loadJS(src, cb){
    var s=document.createElement('script'); s.src=src; s.defer=true;
    s.onload=function(){ try{ cb&&cb(); }catch(e){} };
    document.head.appendChild(s);
  }
  function loadCSS(href){
    var l=document.createElement('link'); l.rel='stylesheet'; l.href=href;
    document.head.appendChild(l);
  }
  function onReady(fn){
    if(document.readyState==='loading'){ document.addEventListener('DOMContentLoaded', fn); }
    else { fn(); }
  }

  onReady(function(){
    var hasPlayer = document.querySelector('.js-player');
    var plyrReady = (window.Plyr && window.Plyr.supported);
    if (hasPlayer && !plyrReady) {
      loadCSS('https://cdn.jsdelivr.net/npm/plyr@3/dist/plyr.css');
      loadJS('https://cdn.jsdelivr.net/npm/plyr@3/dist/plyr.polyfilled.min.js', function(){
        try {
          var nodes = document.querySelectorAll('.js-player');
          for (var i=0;i<nodes.length;i++){ new Plyr(nodes[i]); }
        } catch(e){}
      });
    }
  });
})();
//
